import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def normalize_lockfile(path: Path) -> list[str]:
    """Return dependency content while ignoring generated metadata/comments."""
    lines = []

    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.rstrip()

        if not line:
            continue

        stripped = line.strip()

        # Ignore autogenerated header and dependency provenance comments.
        if stripped.startswith("#"):
            continue

        lines.append(line)

    return lines


def main() -> int:
    source = ROOT / "requirements.in"
    lockfile = ROOT / "requirements.lock"

    if not source.exists():
        print("ERROR: requirements.in is missing")
        return 1

    if not lockfile.exists():
        print("ERROR: requirements.lock is missing")
        return 1

    with tempfile.NamedTemporaryFile(
        suffix=".lock",
        delete=False,
        dir=ROOT,
    ) as tmp:
        generated = Path(tmp.name)

    try:
        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "piptools",
                "compile",
                "--generate-hashes",
                "--output-file",
                str(generated),
                str(source),
            ],
            cwd=ROOT,
            check=False,
        )

        if result.returncode != 0:
            print("ERROR: Unable to regenerate lockfile")
            return result.returncode

        expected = normalize_lockfile(lockfile)
        actual = normalize_lockfile(generated)

        if actual != expected:
            print("ERROR: requirements.lock dependency content is stale")
            print("Run:")
            print(
                "python -m piptools compile "
                "--generate-hashes "
                "--output-file=requirements.lock "
                "requirements.in"
            )
            return 1

        print("requirements.lock dependency content is reproducible and up to date")
        return 0

    finally:
        generated.unlink(missing_ok=True)


if __name__ == "__main__":
    raise SystemExit(main())
